// Parse Claude CLI output and extract JSON
const cliOutput = $input.first().json.stdout || $input.first().json;

let invoiceData;

try {
  // Try direct JSON parse first
  invoiceData = JSON.parse(cliOutput);
} catch (error) {
  // Extract from markdown code block
  const jsonMatch = cliOutput.match(/```json\n([\s\S]*?)\n```/);
  if (jsonMatch) {
    invoiceData = JSON.parse(jsonMatch[1]);
  } else {
    // Try to find any JSON object in the output
    const objMatch = cliOutput.match(/\{[\s\S]*\}/);
    if (objMatch) {
      invoiceData = JSON.parse(objMatch[0]);
    } else {
      throw new Error('Could not extract JSON from Claude CLI output: ' + cliOutput);
    }
  }
}

// Add metadata if available
if ($('Manual Trigger').item.json.id) {
  invoiceData.id = $('Manual Trigger').item.json.id;
}
if ($('Manual Trigger').item.json.threadId) {
  invoiceData.threadId = $('Manual Trigger').item.json.threadId;
}

return {
  json: invoiceData
};
